// SEO checks for the registry in shared/apps.js, the homepage, every about page and sitemap.xml.
// Reads the files on disk (no browser). Run with: node tests/run.mjs seo
// An app with a page (path not starting with '#') needs: one title, a description of 120 to 160 characters,
// a canonical, og and twitter tags, lang and viewport, and JSON-LD that parses (SoftwareApplication and
// BreadcrumbList), plus a sitemap entry. An app that lives on the homepage (path '#...') appears in the
// homepage ItemList instead. Generated by tools/seo/write.mjs from shared/seo/copy.mjs.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import path from 'node:path';
import { existsSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { context, ROOT_LANG } from '../../tools/seo/lang.mjs';
import { canonicalFor, mainApp } from '../../tools/seo/robots.mjs';
import { FACTS } from '../brand-facts.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const SITE = 'https://slopographic.com';
const read = (rel) => readFile(path.join(ROOT, rel), 'utf8');
/** The root language's words (the profile's defaultLang: a build can have another than English at the root). */
const R = context(ROOT_LANG);

/** The registry, read as the browser reads it (a classic script that sets window.SLOP_APPS). */
const win = {};
vm.runInNewContext(await read('shared/apps.js'), { window: win });
const apps = win.SLOP_APPS;
const pageApps = apps.filter((a) => a.path && !a.path.startsWith('#'));
const anchorApps = apps.filter((a) => a.path && a.path.startsWith('#'));
const aboutOf = (a) => `${a.path}about/index.html`;
const aboutApps = pageApps.filter((a) => existsSync(path.join(ROOT, aboutOf(a))));

// A single-app site's root is its app's page (tools/seo/mainapp.mjs, tests/seo/robots-site.test.mjs): no homepage of its own.
// A page's canonical and og:url are its address as the profile names it (robots.mjs canonicalFor; its own on this site).
const MAIN = mainApp();
const INDEXED = { skip: !FACTS.seoIndex && 'the site is not indexed (seo.index): no sitemap (tests/seo/robots.test.mjs)' };
/** Every page this test checks: [{ label, file, url, app }]. */
const pages = [
  ...(MAIN ? [] : [{ label: 'homepage', file: 'index.html', url: `${SITE}/` }]),
  ...pageApps.map((a) => ({ label: a.id, file: `${a.path}index.html`, url: `${SITE}/${a.path}`, app: a })),
  ...aboutApps.map((a) => ({ label: `${a.id} about`, file: aboutOf(a), url: `${SITE}/${a.path}about/`, app: a, about: true })),
];

const meta = (html, re) => { const m = html.match(re); return m ? m[1] : null; };
const titleOf = (html) => meta(html, /<title>([^<]*)<\/title>/);
const descOf = (html) => meta(html, /<meta\s+name="description"\s+content="([^"]*)"/);
const canonicalOf = (html) => meta(html, /<link\s+rel="canonical"\s+href="([^"]*)"/);
const ogOf = (html, prop) => meta(html, new RegExp(`<meta\\s+property="og:${prop}"\\s+content="([^"]*)"`));
const twitterOf = (html, name) => meta(html, new RegExp(`<meta\\s+name="twitter:${name}"\\s+content="([^"]*)"`));
const ldOf = (html) => [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => JSON.parse(m[1]));
const byType = (blocks, type) => blocks.filter((b) => b['@type'] === type);
const html = {};
for (const p of pages) html[p.label] = await read(p.file);

test('every app page, about page and the homepage exist', () => {
  for (const p of pages) assert.ok(existsSync(path.join(ROOT, p.file)), `${p.label}: missing ${p.file}`);
  for (const a of pageApps) assert.ok(a.id, 'a registry entry has no id');
});

test('each page has one title, unique across the site', () => {
  const seen = new Map();
  for (const p of pages) {
    const t = titleOf(html[p.label]);
    assert.ok(t && t.trim(), `${p.label}: no <title>`);
    assert.equal((html[p.label].match(/<title>/g) || []).length, 1, `${p.label}: more than one <title>`);
    assert.ok(!seen.has(t), `${p.label}: title repeats ${seen.get(t)}: ${t}`);
    seen.set(t, p.label);
  }
});

// the lengths (120 to 160) are this site's copy: tests/seo/site-copy.test.mjs (repo-only; a build's renamed copy differs)
test('each page has a description, unique across the site', () => {
  const seen = new Map();
  for (const p of pages) {
    const d = descOf(html[p.label]);
    assert.ok(d, `${p.label}: no meta description`);
    assert.ok(!seen.has(d), `${p.label}: description repeats ${seen.get(d)}`);
    seen.set(d, p.label);
  }
});

test('each page has a canonical link to its own URL', () => {
  for (const p of pages) assert.equal(canonicalOf(html[p.label]), canonicalFor(p.url), `${p.label}: canonical`);
});

test('each page has lang, viewport, and Open Graph and Twitter tags with an image that exists', () => {
  for (const p of pages) {
    const h = html[p.label];
    assert.match(h, /<html[^>]*\slang="[A-Za-z-]+"/, `${p.label}: html lang`);
    assert.match(h, /<meta name="viewport" content="width=device-width/, `${p.label}: viewport`);
    assert.equal(ogOf(h, 'title'), titleOf(h), `${p.label}: og:title matches title`);
    assert.equal(ogOf(h, 'url'), canonicalFor(p.url), `${p.label}: og:url`);
    assert.equal(ogOf(h, 'description'), descOf(h), `${p.label}: og:description matches description`);
    assert.equal(twitterOf(h, 'card'), 'summary_large_image', `${p.label}: twitter:card`);
    const img = ogOf(h, 'image');
    assert.ok(img && img.startsWith(`${SITE}/`), `${p.label}: og:image`);
    assert.ok(existsSync(path.join(ROOT, img.slice(SITE.length + 1))), `${p.label}: og:image file ${img} is missing`);
    assert.equal(twitterOf(h, 'image'), img, `${p.label}: twitter:image matches og:image`);
  }
});

test('each app page has SoftwareApplication and BreadcrumbList JSON-LD that parse', () => {
  for (const p of pageApps.map((a) => pages.find((x) => x.label === a.id))) {
    const app = p.app;
    const blocks = ldOf(html[p.label]);
    const [sw] = byType(blocks, 'SoftwareApplication');
    assert.ok(sw, `${p.label}: no SoftwareApplication`);
    assert.equal(sw.name, app.name, `${p.label}: name`);
    assert.ok(sw.applicationCategory, `${p.label}: applicationCategory`);
    assert.equal(sw.operatingSystem, 'Any (runs in a web browser)', `${p.label}: operatingSystem`);
    assert.equal(sw.offers['@type'], 'Offer', `${p.label}: offers type`);
    assert.equal(sw.offers.price, '0', `${p.label}: price`);
    assert.equal(sw.offers.priceCurrency, 'USD', `${p.label}: priceCurrency`);
    // the meta tag's text is HTML-escaped (P&amp;L); the JSON-LD holds the plain text (P&L)
    const plain = descOf(html[p.label]).replace(/&(amp|lt|gt|quot|#39);/g, (m, e) => ({ amp: '&', lt: '<', gt: '>', quot: '"', '#39': "'" })[e]);
    assert.equal(sw.description, plain, `${p.label}: JSON-LD description`);
    assert.equal(sw.url, p.url, `${p.label}: url`);
    assert.equal(sw.author.name, 'Slopographic', `${p.label}: author`);
    const [crumbs] = byType(blocks, 'BreadcrumbList');
    assert.ok(crumbs, `${p.label}: no BreadcrumbList`);
    assert.deepEqual(crumbs.itemListElement.map((i) => i.name), [R.t('seo.ui.crumb.home'), app.name], `${p.label}: breadcrumb`);
    assert.equal(crumbs.itemListElement[1].item, p.url, `${p.label}: breadcrumb link`);
  }
});

test('each about page has a BreadcrumbList with three levels', () => {
  for (const p of pages.filter((x) => x.about)) {
    const [crumbs] = byType(ldOf(html[p.label]), 'BreadcrumbList');
    assert.ok(crumbs, `${p.label}: no BreadcrumbList`);
    assert.deepEqual(crumbs.itemListElement.map((i) => i.name), [R.t('seo.ui.crumb.home'), p.app.name, R.t('seo.ui.crumb.about')], `${p.label}: breadcrumb`);
  }
});

test('the homepage has an ItemList of every app and the Organization schema', { skip: !!MAIN && 'a single-app site: its root is the app' }, () => {
  const blocks = ldOf(html.homepage);
  const [list] = byType(blocks, 'ItemList');
  assert.ok(list, 'homepage: no ItemList');
  assert.equal(list.numberOfItems, apps.length, 'homepage: ItemList count');
  const names = list.itemListElement.map((i) => i.name);
  for (const a of apps) assert.ok(names.includes(a.name), `homepage: ItemList is missing ${a.name}`);
  const [org] = byType(blocks, 'Organization');
  assert.ok(org, 'homepage: no Organization');
  assert.equal(org.name, 'Slopographic');
  assert.equal(org.url, `${SITE}/`);
});

test('every app in the registry is in the sitemap (anchor apps through the homepage)', INDEXED, async () => {
  const xml = await read('sitemap.xml');
  const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
  assert.equal(new Set(locs).size, locs.length, 'sitemap has duplicate entries');
  for (const p of pages) assert.ok(locs.includes(canonicalFor(p.url)), `sitemap is missing ${canonicalFor(p.url)}`);
  for (const l of locs) {
    const rel = l.slice(SITE.length);
    const file = rel.endsWith('/') ? `${rel}index.html` : rel;
    assert.ok(existsSync(path.join(ROOT, file)), `sitemap lists ${l}, which has no page`);
  }
  for (const m of xml.matchAll(/<url>[\s\S]*?<\/url>/g)) assert.match(m[0], /<lastmod>\d{4}-\d{2}-\d{2}<\/lastmod>/, `no lastmod: ${m[0]}`);
});

test('robots.txt allows crawling and points to the sitemap (none on a site that is not indexed)', async () => {
  const t = await read('robots.txt');
  assert.match(t, /^User-agent: \*$/m);
  assert.match(t, /^Allow: \/$/m);
  assert.ok(!/^Disallow: \/$/m.test(t), 'robots.txt blocks the whole site');
  if (FACTS.seoIndex) assert.match(t, new RegExp(`^Sitemap: ${SITE}/sitemap\\.xml$`, 'm'));
  else assert.doesNotMatch(t, /Sitemap:/);
});
